.community {
  .nav {
    width: 100%;
    height: 48px;
    padding: 0 12px;
    position: relative;
    overflow: hidden;

    img {
      width: 64px;
      height: 16px;
      display: block;
    }

    .clover {
      width: 52px;
      height: 54px;
      display: block;
      position: absolute;
      top: 9px;
      right: 91px;
    }

    .title {
      color: #333333;
      font-size: 15px;
    }

    .more {
      font-weight: 400;
      color: #999999;
      font-size: 12px;

      .iconfont {
        font-size: 12px;
      }
    }
  }

  .list {
    padding: 12px 10px;

    &.on {
      flex-wrap: nowrap;
      overflow: hidden;

      .item {
        margin-right: 12px;
        margin-bottom: 0;

        .pictrue {
          width: 140px;
          height: 175px;
          border-radius: 8px;

          .bottom {
            color: #fff;
            font-weight: 400;
            position: absolute;
            bottom: 0;
            width: 100%;
            padding: 6px 8px;
            z-index: 10;

            .title {
              font-size: 12px;
            }

            .name {
              font-size: 9px;
              width: 100px;
            }

            .user {
              width: 17px;
              height: 17px;
              border-radius: 50%;
              margin-right: 4px;

              img {
                width: 100%;
                height: 100%;
              }
            }
          }

          .mask {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 10;
            background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.4) 100%);
          }
        }
      }
    }

    .item {
      margin-bottom: 20px;

      &:nth-last-child(1) {
        margin-bottom: 0 !important;
      }

      .pictrue {
        width: 164px;
        height: 205px;
        position: relative;

        img {
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        .empty-box {
          background-color: #F3F9FF;

          img {
            width: 65px;
            height: 50px;
            display: block;
          }
        }
      }

      .info {
        font-weight: 400;
        width: 164px;

        .title {
          font-size: 13px;
          color: #333333;
          margin-top: 10px;
        }

        .num {
          font-size: 10px;
          color: #999999;

          .iconfont {
            margin-right: 5px;
            font-size: 12px;
          }
        }

        .txtPic {
          margin-top: 11px;

          .user {
            width: 16px;
            height: 16px;

            img {
              width: 100%;
              height: 100%;
              border-radius: 50%;
            }
          }

          .name {
            font-size: 10px;
            color: #999999;
            margin-left: 4px;
          }
        }
      }
    }
  }
}
